import { test, expect } from '@playwright/test';

test.describe('Search functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display the latest search result', async ({ page }) => {
    await page.fill(getByLabel('Search'), 'test query');
    await page.click(getByRole('button', { name: 'Search' }));

    // Simulate a delay for race condition
    await page.waitForTimeout(100); // Adjust timeout as necessary

    await page.fill(getByLabel('Search'), 'test query updated');
    await page.click(getByRole('button', { name: 'Search' }));

    const latestResult = await page.getByText('Expected latest result'); // Replace with actual expected text
    await expect(latestResult).toBeVisible();
  });

  test('should not show outdated search results', async ({ page }) => {
    await page.fill(getByLabel('Search'), 'initial query');
    await page.click(getByRole('button', { name: 'Search' }));

    // Simulate a delay for race condition
    await page.waitForTimeout(100); // Adjust timeout as necessary

    await page.fill(getByLabel('Search'), 'initial query updated');
    await page.click(getByRole('button', { name: 'Search' }));

    const outdatedResult = await page.getByText('Expected outdated result'); // Replace with actual outdated text
    await expect(outdatedResult).not.toBeVisible();
  });
});
